import type { RecentSubmissionRow, UserSubmissionDto, VerdictTone } from './types'

const unavailable = '—'

export const formatExecutionTime = (value: number | null | undefined) =>
  typeof value === 'number' && Number.isFinite(value) ? `${value} ms` : unavailable

export const formatMemoryUsage = (value: number | null | undefined) =>
  typeof value === 'number' && Number.isFinite(value) ? `${value} MB` : unavailable

export const formatSubmissionDate = (value: string) => {
  const date = new Date(value)
  return Number.isNaN(date.getTime())
    ? unavailable
    : new Intl.DateTimeFormat('es-BO', {
        dateStyle: 'short',
        timeStyle: 'short',
      }).format(date)
}

export const mapSubmissionVerdict = (
  verdict: string,
): { label: string; tone: VerdictTone } => {
  const values: Record<string, { label: string; tone: VerdictTone }> = {
    Accepted: { label: 'ACEPTADO', tone: 'success' },
    'Wrong Answer': { label: 'RESPUESTA INCORRECTA', tone: 'danger' },
    'Time Limit Exceeded': { label: 'TIEMPO LÍMITE EXCEDIDO', tone: 'warning' },
    'Memory Limit Exceeded': { label: 'MEMORIA LÍMITE EXCEDIDA', tone: 'warning' },
    'Compilation Error': { label: 'ERROR DE COMPILACIÓN', tone: 'danger' },
    'Runtime Error': { label: 'ERROR DE EJECUCIÓN', tone: 'danger' },
    Pendiente: { label: 'EVALUANDO', tone: 'info' },
  }
  return values[verdict] ?? { label: verdict || unavailable, tone: 'neutral' }
}

export const mapSubmissionRow = (submission: UserSubmissionDto): RecentSubmissionRow => {
  const verdict = mapSubmissionVerdict(submission.veredicto)
  return {
    id: submission.idEnvio,
    contestCode: submission.concursoCodigo,
    problemLabel: [submission.inciso, submission.problemaTitulo]
      .filter(Boolean)
      .join(' · '),
    language: submission.lenguaje,
    verdictLabel: verdict.label,
    verdictTone: verdict.tone,
    timeLabel: formatExecutionTime(submission.consumoTiempo),
    memoryLabel: formatMemoryUsage(submission.consumoMemoria),
    submittedAtLabel: formatSubmissionDate(submission.fechaEnvio),
  }
}

export const formatPaginationMetadata = ({
  total,
  pagina,
  tamanoPagina,
  received,
}: {
  total: number
  pagina: number
  tamanoPagina: number
  received: number
}) => {
  if (total <= 0 || received <= 0) return '0 envíos'
  const start = (pagina - 1) * tamanoPagina + 1
  const end = Math.min(total, start + received - 1)
  return `Mostrando ${start}-${end} de ${total} envíos`
}

import { endpoints, httpClient } from '@/lib/api'
import type {
  UserContestStats,
  UserSubmissionsParams,
  UserSubmissionsResponse,
} from './types'

export const getUserContestStats = () =>
  httpClient.get<UserContestStats>(endpoints.contests.userStats)

export const listUserSubmissions = (params: UserSubmissionsParams) => {
  const query = new URLSearchParams()
  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined && value !== '') query.set(key, String(value))
  }
  return httpClient.get<UserSubmissionsResponse>(
    `${endpoints.contests.userSubmissions}?${query.toString()}`,
  )
}

import { Alert, Card, Skeleton } from '@/components/common'
import { useUserContestStats } from './hooks'

const statLabels = [
  ['concursosParticipados', 'Concursos participados'],
  ['problemasResueltos', 'Problemas resueltos'],
  ['problemasPendientes', 'Problemas pendientes'],
  ['precisionPorcentaje', 'Precisión'],
] as const

export function UserContestStatsSection() {
  const { data, error, isLoading } = useUserContestStats()
  if (error) return <Alert tone="danger">No se pudieron cargar tus estadísticas.</Alert>

  return (
    <section aria-labelledby="user-stats-title">
      <h1 id="user-stats-title" className="text-2xl font-bold">
        Tu actividad
      </h1>
      <div className="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {statLabels.map(([key, label]) => (
          <Card key={key} className="p-4">
            <p className="text-sm text-[var(--text-secondary)]">{label}</p>
            {isLoading ? (
              <Skeleton className="mt-2 h-8 w-16" />
            ) : (
              <p className="mt-2 text-2xl font-bold">
                {data?.[key] ?? 0}
                {key === 'precisionPorcentaje' ? '%' : ''}
              </p>
            )}
          </Card>
        ))}
      </div>
    </section>
  )
}

import { Badge, DataTable } from '@/components'
import type { RecentSubmissionRow } from './types'

type Props = {
  rows: RecentSubmissionRow[]
  loading?: boolean
  error?: string
}

export function RecentSubmissionsTable({ rows, loading, error }: Props) {
  return (
    <DataTable
      rows={rows}
      loading={loading}
      error={error}
      emptyText="Todavía no tenés envíos recientes."
      className="mt-4"
      columns={[
        { key: 'id', header: 'ID' },
        { key: 'contestCode', header: 'CONCURSO' },
        { key: 'language', header: 'LENGUAJE' },
        { key: 'problemLabel', header: 'PROBLEMA' },
        {
          key: 'verdictLabel',
          header: 'VEREDICTO',
          render: (row) => <Badge tone={row.verdictTone}>{row.verdictLabel}</Badge>,
        },
        { key: 'timeLabel', header: 'TIEMPO' },
        { key: 'memoryLabel', header: 'MEMORIA' },
        { key: 'submittedAtLabel', header: 'FECHA' },
      ]}
    />
  )
}

import { RefreshCw } from 'lucide-react'
import { Alert, Button, Card } from '@/components/common'
import { useUserSubmissions } from './hooks'
import { formatPaginationMetadata, mapSubmissionRow } from './mapper'
import { RecentSubmissionsTable } from './RecentSubmissionsTable'

const recentParams = { pagina: 1, tamanoPagina: 5 }

export function RecentSubmissionsSection() {
  const { data, error, isLoading, isFetching, refetch } =
    useUserSubmissions(recentParams)
  const rows = data?.datos.map(mapSubmissionRow) ?? []
  const refresh = () => {
    if (!isFetching) void refetch()
  }

  return (
    <Card className="mt-6 overflow-hidden p-0">
      <section aria-labelledby="recent-submissions-title">
        <div className="flex flex-col gap-4 border-b border-[var(--border)] p-5 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 id="recent-submissions-title" className="text-xl font-bold">
              Envíos recientes
            </h2>
            <p className="mt-1 text-sm text-[var(--text-secondary)]">
              Historial de tus participaciones recientes en concursos.
            </p>
          </div>
          <Button
            variant="outline"
            leftIcon={<RefreshCw className="size-4" aria-hidden="true" />}
            loading={isFetching && !isLoading}
            disabled={isFetching}
            onClick={refresh}
            aria-label="Actualizar envíos recientes"
          >
            Actualizar
          </Button>
        </div>
        {error ? (
          <div className="p-5">
            <Alert tone="danger">No se pudieron cargar los envíos recientes.</Alert>
          </div>
        ) : (
          <>
            <RecentSubmissionsTable rows={rows} loading={isLoading} />
            {data && (
              <p className="px-5 py-4 text-sm text-[var(--text-secondary)]">
                {formatPaginationMetadata({
                  total: data.total,
                  pagina: data.pagina,
                  tamanoPagina: data.tamanoPagina,
                  received: data.datos.length,
                })}
              </p>
            )}
          </>
        )}
      </section>
    </Card>
  )
}

import { RecentSubmissionsSection } from '@/features/contests/user/RecentSubmissionsSection'
import { UserContestStatsSection } from '@/features/contests/user/UserContestStatsSection'

export default function UserLandingPage() {
  return (
    <div>
      <UserContestStatsSection />
      <RecentSubmissionsSection />
    </div>
  )
}

